mapper.select:
SELECT od.order_record_id AS orderRecordId, ${billPayId} AS billPayId, od.id AS orderDetailId, od.type AS itemType, od.billing_item_id AS itemId, od.executor_id AS executorId, od.consulter_id AS consulterId, odpr.privilege_date AS privilegeDate, odpr.receivable_amount AS receivableAmount, odpr.actual_receivable AS actualReceivable, IFNULL(odpr.tariffActualAmount, 0) AS tariffActualAmount, IFNULL(odpr.oralActualAmount, 0) AS oralActualAmount, IFNULL(odpr.tariffReceivableAmount, 0) AS tariffReceivableAmount, IFNULL(odpr.oralReceivableAmount, 0) AS oralReceivableAmount, IFNULL(bdp.free_amount, 0) AS itemFreeAmount, IFNULL(bdp.received_amount, 0) AS itemRecAmount, IF(bdp.swipe_workload>0, 0, odpr.swipe_workload) AS swipeWorkload -- 0 AS swipeWorkload FROM order_detail od LEFT JOIN ( SELECT odpr.order_record_id, odpr.order_detail_id, br.privilege_date, odpr.swipe_workload, odpr.receivable_amount, odpr.actual_receivable, bd.tariffActualAmount, bd.oralActualAmount, bd.tariffReceivableAmount, bd.oralReceivableAmount FROM order_detail_pay_record odpr LEFT JOIN bill_record br ON odpr.bill_record_id = br.id LEFT JOIN ( SELECT od.order_record_id, SUM(IF(od.type=0, odpr.actual_receivable, 0)) AS tariffActualAmount, SUM(IF(od.type=1, odpr.actual_receivable, 0)) AS oralActualAmount, SUM(IF(od.type=0, odpr.receivable_amount, 0)) AS tariffReceivableAmount, SUM(IF(od.type=1, odpr.receivable_amount, 0)) AS oralReceivableAmount FROM order_detail od LEFT JOIN order_detail_pay_record odpr ON odpr.order_detail_id = od.id
AND odpr.order_record_id = #{orderRecordId}
GROUP BY od.order_record_id ) bd ON bd.order_record_id = bd.order_record_id WHERE odpr.order_record_id = #{orderRecordId} ) odpr ON odpr.order_detail_id = od.id LEFT JOIN ( SELECT order_record_id, item_type, item_id, sum(free_amount) AS free_amount, sum(received_amount) AS received_amount, sum(swipe_workload) AS swipe_workload FROM bill_pay_share_detail
inservice = true AND order_record_id = #{orderRecordId} AND bill_pay_id < #{billPayId}
group by order_record_id, item_type, item_id ) bdp ON bdp.order_record_id=odpr.order_record_id and od.type=bdp.item_type and od.billing_item_id=bdp.item_id
AND od.receivable_amount > 0 AND odpr.order_record_id = #{orderRecordId}
ORDER BY od.type, od.billing_item_id

SELECT od.order_record_id AS orderRecordId, ${billPayId} AS billPayId, od.id AS orderDetailId, od.type AS itemType, od.billing_item_id AS itemId, od.executor_id AS executorId, od.consulter_id AS consulterId, odpr.actual_receivable AS actualReceivable, IFNULL(bd.tariffActualAmount, 0) AS tariffActualAmount, IFNULL(bd.oralActualAmount, 0) AS oralActualAmount, IFNULL(bdp.free_amount, 0) AS itemFreeAmount, IFNULL(bdp.received_amount, 0) AS itemRecAmount, IF(bdp.swipe_workload>0, 0, odpr.swipe_workload) AS swipeWorkload FROM order_detail od LEFT JOIN order_detail_pay_record odpr ON odpr.order_detail_id = od.id LEFT JOIN ( SELECT od.order_record_id, SUM(IF(od.type=0, odpr.actual_receivable, 0)) AS tariffActualAmount, SUM(IF(od.type=1, odpr.actual_receivable, 0)) AS oralActualAmount FROM order_detail od LEFT JOIN order_detail_pay_record odpr ON odpr.order_detail_id = od.id
od.inservice = true AND odpr.inservice = true AND odpr.order_record_id = #{orderRecordId}
GROUP BY od.order_record_id ) bd ON bd.order_record_id=od.order_record_id LEFT JOIN ( SELECT order_record_id, item_type, item_id, sum(free_amount) AS free_amount, sum(received_amount) AS received_amount, sum(swipe_workload) AS swipe_workload FROM bill_pay_share_detail
AND order_record_id = #{orderRecordId} AND bill_pay_id < #{billPayId}
group by order_record_id, item_type, item_id ) bdp ON bdp.order_record_id=od.order_record_id and od.type=bdp.item_type and od.billing_item_id=bdp.item_id
od.inservice = true AND od.receivable_amount > 0 AND odpr.inservice = true AND odpr.order_record_id = #{orderRecordId}
ORDER BY od.type, od.billing_item_id
